def buscar(dado: dict, caminho: str):
    """Caminha pelo JSON. Uma parte inteiramente numérica indexa lista.

    A extensão existe porque o corte do bootstrap sai como lista, um por
    regressor. Cuidado deliberado: "-15%" não é numérico e continua sendo
    chave de dicionário, que é o caso dos limiares discretos.

    Uma chave com ponto dentro ("mu=0.5", "-0.20") não sobrevive ao `split`;
    para ela o caminho vai como tupla, uma parte por nível (v1, 23/09/2026).
    """
    partes = caminho if isinstance(caminho, (list, tuple)) else caminho.split(".")
    for parte in partes:
        if isinstance(parte, int):
            dado = dado[parte]
        else:
            dado = dado[int(parte)] if parte.isdigit() else dado[parte]
    return dado


def formatar(valor: float, casas: int) -> str:
    """Formato pt-BR: vírgula decimal e ponto de milhar, como nos documentos."""
    if casas == 0:
        return f"{int(round(valor)):,}".replace(",", ".")
    return f"{valor:,.{casas}f}".replace(",", "\x00").replace(".", ",").replace("\x00", ".")


def montar(categoria: str, n: int, raiz: Path) -> dict:
    caches: dict[str, dict] = {}
    entradas, ausentes = {}, []
    for chave, fonte, caminho, casas, descricao in MAPA:
        script, molde = PRODUTORES[fonte]
        arquivo = raiz / molde.format(cat=categoria, n=n)
        if fonte not in caches:
            if not arquivo.exists():
                ausentes.append((chave, str(arquivo), script))
                continue
            caches[fonte] = json.loads(arquivo.read_text())
        try:
            valor = float(buscar(caches[fonte], caminho))
        except (KeyError, TypeError):
            ausentes.append((chave, f"{arquivo}:{caminho}", script))
            continue
        entradas[chave] = {
            "valor": valor,
            "texto": formatar(valor, casas),
            "descricao": descricao,
            "produtor": script,
            "saida": str(arquivo.relative_to(raiz)),
            "campo": caminho,
        }
    return {
        "gerado_em": date.today().isoformat(),
        "categoria": categoria,
        "n": n,
        "entradas": entradas,
        "sem_artefato": [{"chave": c, "esperado": a, "produtor": s}
                         for c, a, s in ausentes],
    }


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--categoria", default="frj")
    ap.add_argument("--n", type=int, default=20)
    ap.add_argument("--raiz", default=".")
    ap.add_argument("--saida", default="reports/numeros_oficiais.json")
    a = ap.parse_args()

    registro = montar(a.categoria, a.n, Path(a.raiz))
    destino = Path(a.raiz) / a.saida
    destino.parent.mkdir(parents=True, exist_ok=True)
    destino.write_text(json.dumps(registro, indent=2, ensure_ascii=False))

    print(f"{len(registro['entradas'])} números com produtor declarado")
    for chave, e in registro["entradas"].items():
        print(f"  {chave:28s} {e['texto']:>12s}   {e['produtor']}")
    if registro["sem_artefato"]:
        print(f"\n{len(registro['sem_artefato'])} SEM ARTEFATO (rode o produtor):")
        for f in registro["sem_artefato"]:
            print(f"  {f['chave']:28s} falta {f['esperado']}  -> {f['produtor']}")
    print(f"\ngravado em {destino}")


if __name__ == "__main__":
    main()
